{
  "rules": [
    {
      "category": "just_cause_eviction",
      "title": "Statewide just cause eviction protections (AB 1482)",
      "requirement": "Landlords cannot terminate a tenancy without stating an allowed at-fault or no-fault just cause once all tenants have continuously occupied the unit for at least 12 months (or 24 months if adult tenants were added). For no-fault evictions, the landlord must provide relocation assistance equal to one month of rent or waive the final month's rent.",
      "requirement_es": "Los propietarios no pueden rescindir un contrato de arrendamiento sin declarar una causa justa permitida (con o sin culpa) una vez que todos los inquilinos hayan ocupado continuamente la vivienda durante al menos 12 meses (o 24 meses si se añadieron adultos). En los desalojos sin culpa, el propietario debe proporcionar asistencia para la reubicación equivalente a un mes de alquiler o condonar el alquiler del último mes.",
      "key_value": {
        "label": "relocation assistance",
        "value": "1 month of rent"
      },
      "coverage_conditions": {
        "type": "OR",
        "clauses": [
          {
            "field": "tenancy_length_months",
            "operator": ">=",
            "value": 12,
            "note": "after a tenant has continuously and lawfully occupied a residential real property for 12 months"
          },
          {
            "field": "tenancy_length_months",
            "operator": ">=",
            "value": 24,
            "note": "One or more tenants have continuously and lawfully occupied the residential real property for 24 months or more"
          }
        ]
      },
      "exemptions": [
        {
          "description": "Housing issued a certificate of occupancy within the previous 15 years, unless the housing is a mobilehome",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "building_age_years",
                "operator": "<",
                "value": 15,
                "note": "issued a certificate of occupancy within the previous 15 years"
              },
              {
                "field": "property_type",
                "operator": "!=",
                "value": "mobile_home",
                "note": "unless the housing is a mobilehome"
              }
            ]
          }
        },
        {
          "description": "Single-family homes, condominiums, and alienable units not owned by a corporation, REIT, or LLC with corporate members, provided required disclosure notice was given",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "property_type",
                "operator": "in",
                "value": [
                  "single_family",
                  "condominium"
                ],
                "note": "alienable separate from the title to any other dwelling unit"
              },
              {
                "field": "owner_type",
                "operator": "not_in",
                "value": [
                  "corporation",
                  "reit",
                  "llc"
                ],
                "note": "The owner is not a real estate investment trust, a corporation, or a limited liability company in which at least one member is a corporation"
              }
            ]
          }
        },
        {
          "description": "Owner-occupied duplex where the owner occupied one of the units at the beginning of the tenancy and continues occupancy",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "units",
                "operator": "==",
                "value": 2,
                "note": "property containing two separate dwelling units within a single structure"
              },
              {
                "field": "owner_occupied",
                "operator": "==",
                "value": true,
                "note": "owner occupied one of the units as the owner's principal place of residence"
              }
            ]
          }
        },
        {
          "description": "Single-family owner-occupied residence renting no more than two units or bedrooms",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "property_type",
                "operator": "==",
                "value": "single_family",
                "note": "Single-family owner-occupied residences"
              },
              {
                "field": "owner_occupied",
                "operator": "==",
                "value": true,
                "note": "Single-family owner-occupied residences"
              }
            ]
          }
        },
        {
          "description": "Deed-restricted affordable housing or government-subsidized housing",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "rent_subsidized",
                "operator": "==",
                "value": true,
                "note": "Housing restricted by deed, regulatory restriction... or subject to an agreement that provides housing subsidies"
              }
            ]
          }
        },
        {
          "description": "Transient and tourist hotel occupancy, institutional dormitories, care facilities, or shared kitchen/bath with owner",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "owner_type",
                "operator": "==",
                "value": "__unknowable__"
              }
            ]
          }
        }
      ],
      "effective_date": "2026-01-01",
      "superseded_date": "2030-01-01",
      "status": "enacted",
      "precedence": {
        "relationship": "yields_to",
        "target_scope": "local",
        "source_language": "This section does not apply to the following residential real property: (A) Residential real property subject to a local ordinance requiring just cause for termination of a residential tenancy adopted on or before September 1, 2019, in which case the local ordinance shall apply. (B) Residential real property subject to a local ordinance requiring just cause for termination of a residential tenancy adopted or amended after September 1, 2019, that is more protective than this section, in which case the local ordinance shall apply."
      },
      "penalty": "Failure to comply renders notice void. Owner liable for actual damages, reasonable attorney's fees and costs, and up to treble actual damages and punitive damages for willful, oppressive, fraudulent, or malicious conduct. Injunctive relief also available.",
      "source_citation": "Cal. Civ. Code § 1946.2",
      "quote": {
        "chunk": "c1",
        "start_words": "Notwithstanding any other law, after a tenant",
        "end_words": "written notice to terminate tenancy."
      },
      "confidence": 0.98
    }
  ]
}
